	/**
	 * Extract the agent's final answer as structured data, comparable to the golden SQL result.
	 *
	 * Small results are retyped by the model; larger ones are resolved from the cached query
	 * results the agent already produced, since no model retypes hundreds of rows reliably.
	 */
	async runVerification(
		projectId: string,
		agentResult: AgentRunResult,
		expected: { columns: string[]; rowCount: number },
		modelSelection?: LlmSelectedModel,
	): Promise<VerificationResult> {
		if (expected.rowCount > MAX_VERIFIABLE_ROWS) {
			return {
				data: null,
				error: `the expected result has ${expected.rowCount} rows, above the ${MAX_VERIFIABLE_ROWS} row verification limit`,
			};
		}

		const queryResults = TestAgentService._collectQueryResults(agentResult);
		const messages = TestAgentService._buildVerificationMessages(agentResult, queryResults);

		return expected.rowCount > MAX_INLINE_ROWS
			? this._verifyFromCachedQuery(projectId, messages, expected.columns, queryResults, modelSelection)
			: this._verifyFromInlineRows(projectId, messages, expected.columns, modelSelection);
	}

	private async _verifyFromInlineRows(
		projectId: string,
		messages: ModelMessage[],
		expectedColumns: string[],
		modelSelection?: LlmSelectedModel,
	): Promise<VerificationResult> {
		const valueSchema = z.union([z.string(), z.number(), z.boolean(), z.null()]);
		const rowSchema = z.object(
			Object.fromEntries(expectedColumns.map((col) => [col, valueSchema.describe(`Value for column ${col}`)])),
