const CATALOG_SAMPLE_ROWS = 5;

function renderQueryResult(ref: QueryResultRef): string {
	const header = `Query ID: ${ref.id}\nColumns: ${ref.columns.join(', ')}\nRows: ${ref.data.length}`;
	if (ref.data.length <= MAX_INLINE_ROWS) {
