/**
 * Reasoning models can answer with several complete JSON objects emitted as separate text parts,
 * which the AI SDK concatenates into one unparseable string. Recover the model's final answer.
 */
export async function repairConcatenatedJson({ text }: { text: string }): Promise<string | null> {
	const values = splitTopLevelJsonValues(text);
	return values.length > 1 ? values[values.length - 1]! : null;
}

function splitTopLevelJsonValues(text: string): string[] {
	const values: string[] = [];
	let depth = 0;
	let start = -1;
	let inString = false;
	let escaped = false;

	for (let index = 0; index < text.length; index++) {
		const char = text[index];

		if (inString) {
			if (escaped) {
				escaped = false;
			} else if (char === '\\') {
				escaped = true;
			} else if (char === '"') {
				inString = false;
			}
			continue;
		}

		if (char === '"') {
			inString = true;
		} else if (char === '{' || char === '[') {
			if (depth === 0) {
				start = index;
			}
			depth++;
		} else if (char === '}' || char === ']') {
			depth--;
			if (depth === 0 && start !== -1) {
				values.push(text.slice(start, index + 1));
				start = -1;
			}
		}
	}

	return values;
}

function toCsv(columns: string[], rows: Record<string, unknown>[]): string {
	const lines = [columns.map(escapeCsvField).join(',')];
	for (const row of rows) {
		lines.push(columns.map((column) => escapeCsvField(formatCsvValue(row[column]))).join(','));
	}
	return lines.join('\n');
}

function formatCsvValue(value: unknown): string {
	if (value === null || value === undefined) {
		return '';
	}
	return typeof value === 'object' ? JSON.stringify(value) : String(value);
}

function escapeCsvField(value: string): string {
	return /[",\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

function toComparableValue(value: unknown): string | number | boolean | null {
	if (value === null || value === undefined) {
		return null;
	}
	if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
		return value;
	}
	return String(value);
}

